import type { TournamentData, GroupId, Stage } from "../domain/types.ts";
import type { STATUSES } from "./calendar-mapping.ts";
export type CalendarStatus = (typeof STATUSES)[number];

/** Read projections of the confirmed columns, NOT autogenerated database types.
 * SQL types/nullability were not supplied, so all values are validated at runtime. */
export type ReadRow = Readonly<Record<string, unknown>>;
export type ReadTable =
  "tournaments" | "groups" | "teams" | "matchdays" | "matches";
export interface ReadFilter {
  column: "slug" | "tournament_id";
  value: string;
}
export interface TournamentReader {
  read(table: ReadTable, filter: ReadFilter): Promise<readonly ReadRow[]>;
}
export interface SupabaseCalendarRows {
  tournaments: readonly ReadRow[];
  groups: readonly ReadRow[];
  teams: readonly ReadRow[];
  matchdays: readonly ReadRow[];
  matches: readonly ReadRow[];
}
export interface CalendarMetadata {
  source: "supabase";
  tournament: {
    id: string;
    slug: string;
    name: string;
    season: unknown;
    location: unknown;
  };
  groups: { id: string; name: string; localGroup: GroupId }[];
  teams: {
    id: string;
    slug: string;
    localSlug: string;
    name: string;
    groupId: string;
  }[];
  matchdays: {
    id: string;
    number: number;
    phase: string;
    scheduledDate: string | null;
  }[];
  matches: {
    id: string;
    localId: string;
    matchNumber: number;
    phase: string;
    localStage: Stage;
    bracketCode: string | null;
    matchdayId: string | null;
    groupId: string | null;
    homeTeamId: string | null;
    awayTeamId: string | null;
    homeSource: string | null;
    awaySource: string | null;
    status: CalendarStatus;
    scheduledAt: string | null;
    venue: string | null;
  }[];
  notices: { code: string; matchId: string; message: string }[];
}
export interface CalendarReadSnapshot {
  data: TournamentData;
  metadata: CalendarMetadata;
}
export class SupabaseReadError extends Error {
  readonly code: string;
  constructor(code: string, message: string) {
    super(message);
    this.code = code;
    this.name = "SupabaseReadError";
  }
}
